fn roll::(sides) {
    return @rand_int(1, sides);
}
fn pick::(xs) {
    if (@len(xs) == 0) { return null; }
    return xs[@rand_int(0, @len(xs) - 1)];
}
fn shuffle::(xs) {
    let i = @len(xs) - 1;
    while (i > 0) {
        let j = @rand_int(0, i);
        let t = xs[i]; xs[i] = xs[j]; xs[j] = t;
        i = i - 1;
    }
    return xs;
}
fn dice::(n, sides) {
    let s = 0; let i = 0;
    while (i < n) { s = s + @rand_int(1, sides); i = i + 1; }
    return s;
}
